NEW_SOURCE='from __future__ import annotations\nfrom dataclasses import dataclass\nfrom pathlib import Path\nfrom .oad_148_solana_mainnet_chain_state_acquisition import _rpc\nfrom .oad_323_solana_durable_slot_checkpoint import load_solana_chain_checkpoint,commit_solana_chain_checkpoint\nfrom .oad_324_solana_gap_backfill_recovery_planner import build_solana_recovery_plan\nfrom .oad_325_solana_universal_single_writer_persistence import persist_solana_universal_chain_batch\nREAD_ONLY=True;PROBABILITY_ENABLED=False;DIRECTION_ENABLED=False;PUBLICATION_ALLOWED=False;EXECUTION_AUTHORITY=False\n\n@dataclass(frozen=True,slots=True)\nclass SolanaUniversalWorkerCycle:\n    head_slot:int;before_slot:int|None;after_slot:int|None;mode:str;requested_slots:int;transactions:int;observations:int;committed_events:int;state:str;execution_authority:bool=False\n\ndef _adaptive_batch_size(gap_slots,cap=32):\n    gap=max(0,int(gap_slots)); cap=max(1,min(int(cap),32))\n    if gap<=4: desired=gap\n    elif gap<=16: desired=8\n    elif gap<=64: desired=16\n    else: desired=32\n    return min(cap,gap,desired)\n\ndef run_solana_universal_worker_cycle(root=None,per_batch_limit=32,timeout_seconds=180.0,acquisition_timeout_seconds=20.0):\n    root=Path(root or Path.cwd()).resolve()\n    head=int(_rpc("getSlot",[{"commitment":"finalized"}],acquisition_timeout_seconds))\n    plan=build_solana_recovery_plan(head,root)\n    before=load_solana_chain_checkpoint(root)\n    if plan.gap_slots<=0:\n        return SolanaUniversalWorkerCycle(head,before.last_committed_slot,before.last_committed_slot,plan.mode,0,0,0,0,"CAUGHT_UP",False)\n    count=_adaptive_batch_size(plan.gap_slots,per_batch_limit)\n    p=persist_solana_universal_chain_batch(plan.start_slot,count,root,timeout_seconds,acquisition_timeout_seconds)\n    if p.coverage_state!="UNIVERSAL_BATCH_ACCOUNTED":\n        raise RuntimeError("coverage gate refused checkpoint advance")\n    if int(p.observations)!=int(p.committed_events):\n        raise RuntimeError("exact PostgreSQL readback did not account for full Solana batch")\n    target=int(plan.start_slot)+int(count)-1\n    commit_solana_chain_checkpoint(target,None,root)\n    return SolanaUniversalWorkerCycle(head,before.last_committed_slot,target,plan.mode,count,int(p.transactions),int(p.observations),int(p.committed_events),"COMMITTED",False)\n'
TEST_SOURCE='import unittest\nfrom types import SimpleNamespace\nfrom unittest.mock import patch\nfrom qseries_v2.oracle_adapters.independent import oad_326_solana_universal_resilient_worker as m\nclass T(unittest.TestCase):\n    def test_deep_backlog_is_one_32_slot_atomic_request(self):\n        calls=[]; checkpoints=[]\n        with patch.object(m,"_rpc",return_value=1000), patch.object(m,"build_solana_recovery_plan",return_value=SimpleNamespace(gap_slots=500,start_slot=101,mode="BACKFILL")), patch.object(m,"load_solana_chain_checkpoint",return_value=SimpleNamespace(last_committed_slot=100)), patch.object(m,"persist_solana_universal_chain_batch",side_effect=lambda start,limit,*a:(calls.append((start,limit)) or SimpleNamespace(coverage_state="UNIVERSAL_BATCH_ACCOUNTED",transactions=99,observations=120,committed_events=120))), patch.object(m,"commit_solana_chain_checkpoint",side_effect=lambda slot,*a:checkpoints.append(slot)):\n            x=m.run_solana_universal_worker_cycle(".")\n        self.assertEqual(calls,[(101,32)]); self.assertEqual(checkpoints,[132]); self.assertEqual(x.requested_slots,32)\n    def test_failed_batch_never_advances_checkpoint(self):\n        checkpoints=[]\n        with patch.object(m,"_rpc",return_value=1000), patch.object(m,"build_solana_recovery_plan",return_value=SimpleNamespace(gap_slots=500,start_slot=101,mode="BACKFILL")), patch.object(m,"load_solana_chain_checkpoint",return_value=SimpleNamespace(last_committed_slot=100)), patch.object(m,"persist_solana_universal_chain_batch",side_effect=RuntimeError("boom")), patch.object(m,"commit_solana_chain_checkpoint",side_effect=lambda slot,*a:checkpoints.append(slot)):\n            with self.assertRaises(RuntimeError): m.run_solana_universal_worker_cycle(".")\n        self.assertEqual(checkpoints,[])\n    def test_readback_mismatch_fails_closed(self):\n        with patch.object(m,"_rpc",return_value=1000), patch.object(m,"build_solana_recovery_plan",return_value=SimpleNamespace(gap_slots=8,start_slot=101,mode="BACKFILL")), patch.object(m,"load_solana_chain_checkpoint",return_value=SimpleNamespace(last_committed_slot=100)), patch.object(m,"persist_solana_universal_chain_batch",return_value=SimpleNamespace(coverage_state="UNIVERSAL_BATCH_ACCOUNTED",transactions=1,observations=10,committed_events=9)), patch.object(m,"commit_solana_chain_checkpoint") as c:\n            with self.assertRaises(RuntimeError): m.run_solana_universal_worker_cycle(".")\n            c.assert_not_called()\nif __name__=="__main__":\n    rr=unittest.TextTestRunner(verbosity=2).run(unittest.defaultTestLoader.loadTestsFromTestCase(T))\n    if not rr.wasSuccessful(): raise SystemExit(1)\n    print("[PASS] OAD-410 adaptive multi-slot catch-up worker rebuild certified")\n'
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
    if Path(__file__).name!=EXPECTED: raise RuntimeError("installer filename mismatch")
    root=Path.cwd().resolve(); p=root/TARGET
    if not p.is_file() or sha(p)!=EXPECTED_HASH: raise RuntimeError("exact current OAD-326 source mismatch; no mutation performed")
    ast.parse(NEW_SOURCE,filename=str(TARGET))
    stamp=time.strftime("%Y%m%dT%H%M%S"); bak=p.with_name(p.name+".pre_adaptive_multislot_rebuild."+stamp+".bak"); shutil.copy2(p,bak)
    tmp=p.with_suffix(p.suffix+".tmp"); tmp.write_text(NEW_SOURCE,encoding="utf-8",newline="\n"); os.replace(tmp,p)
    (root/"test_oad_410_solana_adaptive_multi_slot_catchup_worker_rebuild.py").write_text(TEST_SOURCE,encoding="utf-8",newline="\n")
    print("[PASS] exact repaired OAD-326 repo source matched")
    print("[PASS] rollback backup:",bak.relative_to(root))
    print("[PASS] deep backlog now persists up to 32 finalized slots in one atomic canonical batch")
    print("[PASS] checkpoint advances only after full batch persistence plus exact readback")
    print("[PASS] failed or incomplete batch cannot advance checkpoint")
    print("[PASS] no second writer; OPH-019/021 single-writer boundary preserved; execution_authority=FALSE")
    print("[DONE]",EXPECTED)
